/// <summary>
/// MPJ_13564_AutoGeneratePaym - kscerri
/// This class is derived from <c>VendSumForPaym</c> for auto payments using batch.
/// </summary>
class METVendSumForPaym extends VendSumForPaym
{
}

Method.Source:
    /// <summary>
    /// Create new instance of <c>METVendSumForPaym</c> class.
    /// </summary>
    /// <param name = "_ledgerJournalId">Journal number to generate payments.</param>
    /// <returns><c>METAMEXCustSumForPaym</c>class instance</returns>
    static METVendSumForPaym construct(LedgerJournalId  _ledgerJournalId)
    {
        LedgerJournalTable          ledgerJournalTable = LedgerJournalTable::find(_ledgerJournalId);
        METVendSumForPaym           custVendSumForPaym = new METVendSumForPaym();

        if (!ledgerJournalTable)
        {
            throw error("@SYS19282");
        }
        custVendSumForPaym.parmLedgerJournalId(_ledgerJournalId);
        custVendSumForPaym.metUnblockJournal();
        custVendSumForPaym.initParmDefault();

        custVendSumForPaym.updateQuery();

        return custVendSumForPaym;
    }

    /// <summary>
    /// Unblock journal <c>LedgerJournalTable</c>
    /// </summary>
    public void metUnblockJournal()
    {
        LedgerJournalTable metJournalTableBlocked = LedgerJournalTable::find(this.parmLedgerJournalId(), true);
        if (metJournalTableBlocked.SystemBlocked)
        {
            ttsbegin;
            metJournalTableBlocked.SystemBlocked = NoYes::No;
            metJournalTableBlocked.doUpdate();
            ttscommit;
        }

    }

    /// <summary>
    /// Create new instance of <c>METVendSumForPaym</c> class.
    /// </summary>
    /// <param name = "_ledgerJournalTrans">LedgerJournalTrans buffer.</param>
    /// <returns><c>METVendSumForPaym</c> instance</returns>
    static METVendSumForPaym newLedgerJournalTrans(LedgerJournalTrans  _ledgerJournalTrans)
    {
        METVendSumForPaym  custVendSumForPaym;

        custVendSumForPaym = METVendSumForPaym::construct(_ledgerJournalTrans.JournalNum);

        return custVendSumForPaym;
    }

    /// <summary>
    /// Runs the generate payment operation.
    /// </summary>
    public void run()
    {
        CustVendPaymModeTable custVendPaymModeTable;

        if (!selectOnPaymFormat && paymMode)
        {
            custVendPaymModeTable = this.paymModeTable();

            if (this.useGERConfiguration())
            {
                this.metExportERPayment(custVendPaymModeTable.ERFormatMappingID);
            }
        }
    }

/// <summary>
/// Run electronic report to generate payment file.
/// </summary>
/// <param name = "_eRFormatMappingID">ER format</param>
void metExportERPayment(ERFormatMappingID _eRFormatMappingID)
{
    var custVendPaymERExport = new CustVendPaymERExport();
    custVendPaymERExport.parmERBinding(_eRFormatMappingID);
    custVendPaymERExport.parmLedgerJournalId(ledgerJournalId);
    custVendPaymERExport.parmBankAccountID(bankAccountID);
    custVendPaymERExport.parmQuery(this.queryRun().query());
    custVendPaymERExport.parmShowParamsDialog(false);
    custVendPaymERExport.parmCustVendPaymModeTable(this.paymModeTable());
    custVendPaymERExport.parmShowDialog(false);
    custVendPaymERExport.parmShowParamsDialog(false);
    custVendPaymERExport.run();
}
